function QuoteForm({onNotice}:{onNotice:(message:string)=>void}){
 const router=useRouter();const [unitPrice,setUnitPrice]=useState("18400");const [qty,setQty]=useState("4");const [vat,setVat]=useState("15");const [brand,setBrand]=useState("FlowTek · V-400 Series");const [lead,setLead]=useState("14");const [error,setError]=useState("");const total=(Number(unitPrice)*Number(qty))*(1+Number(vat)/100);
 const submit=(e:FormEvent)=>{e.preventDefault();if(!brand.trim()||Number(unitPrice)<=0||Number(qty)<=0||Number(lead)<=0){setError("Enter the offered model, a valid price, quantity and lead time.");return}setError("");onNotice("Quotation submitted in the sample workspace. The buyer has not been contacted externally.");router.push("/app/supplier/quotations")};
 return <><PageHeading kicker="SUPPLIER WORKSPACE / QUOTATION" title="Prepare your quotation" description="Respond to RFQ-1026-001 with a clear technical and commercial offer."/><div className="notice" style={{marginBottom:14}}>Industrial valves for water treatment · Al Noor Infrastructure Co. · Riyadh delivery · Closes 29 Oct 2026</div><form className="panel" onSubmit={submit}><div className="panel-title"><div><h2>Offer details</h2><p>Provide one structured response for the requested items.</p></div><span className="demo-chip">SAR · Sample</span></div>{error&&<div className="notice warn" style={{marginBottom:12}} role="alert">{error}</div>}<div className="form-grid"><div className="field"><label>Offered brand / model <i className="required">*</i></label><input required value={brand} onChange={e=>setBrand(e.target.value)}/></div><div className="field"><label>Technical compliance</label><select><option>Compliant with requested specifications</option><option>Compliant with notes</option><option>Alternative offered</option></select></div><div className="field full"><label>Offered technical specifications</label><textarea defaultValue="Ductile iron body, epoxy coated; EPDM seat; PN16 flanged connection; ISO 5211 actuator mounting."/></div><div className="field"><label>Unit price (SAR) <i className="required">*</i></label><input type="number" min="1" value={unitPrice} onChange={e=>setUnitPrice(e.target.value)}/></div><div className="field"><label>Quantity</label><input type="number" min="1" value={qty} onChange={e=>setQty(e.target.value)}/></div><div className="field"><label>VAT (%)</label><select value={vat} onChange={e=>setVat(e.target.value)}><option value="15">15%</option><option value="0">0%</option></select></div><div className="field"><label>Lead time (calendar days)</label><input type="number" min="1" value={lead} onChange={e=>setLead(e.target.value)}/></div><div className="field"><label>Offer type</label><select><option>Supply only</option><option>Supply and installation</option></select></div><div className="field"><label>Offer validity</label><select><option>30 days</option><option>15 days</option><option>45 days</option><option>60 days</option></select></div><div className="field full"><label>Commercial remarks</label><textarea placeholder="Delivery terms, included services, exclusions or other notes for the buyer."/></div></div><div className="notice" style={{marginTop:17,display:"flex",justifyContent:"space-between"}}><span>Estimated offer total including VAT</span><b className="quote-total">{fmtSAR(total||0)}</b></div><div className="form-actions"><Link className="page-link" href="/app/supplier/inbox">Cancel</Link><div><Button variant="outline" type="button" onClick={()=>onNotice("Quotation saved as a draft. It remains private to this workspace.")}>Save draft</Button><Button type="submit">Submit quotation <IconArrowRight size={15}/></Button></div></div></form></>;
}

